    public function up(): void
    {
        if (! Schema::hasTable('products') || ! Schema::hasColumn('products', 'ingredients')) {
            return;
        }

        $rows = json_decode(self::DATA, true);

        if (! is_array($rows) || $rows === []) {
            return;
        }

        $slugs = array_column($rows, 'slug');
        $present = DB::table('products')->whereIn('slug', $slugs)->count();

        if ($present * 2 < count($slugs)) {
            if (app()->runningInConsole()) {
                echo "Ingredients: {$present} of ".count($slugs)." listed products on this shop -- not the live catalogue, nothing changed.\n";
            }

            return;
        }

        $current = DB::table('products')->whereIn('slug', $slugs)->pluck('ingredients', 'slug');
        $filled = 0;
        $kept = 0;

        foreach ($rows as $row) {
            if (! $current->has($row['slug'])) {
                continue;
            }

            if (trim(strip_tags(html_entity_decode((string) $current[$row['slug']]))) !== '') {
                $kept++;
                continue;
            }

            DB::table('products')->where('slug', $row['slug'])->update(['ingredients' => $row['body'], 'updated_at' => now()]);
            $filled++;
        }

        if (class_exists(\App\Support\ProductTabs::class)) {
            \App\Support\ProductTabs::flush();
        }

        foreach ([storage_path('framework/views/*.php')] as $pattern) {
            foreach (glob($pattern) ?: [] as $file) {
                if (is_file($file)) {
                    @unlink($file);
                }
            }
        }

        if (function_exists('opcache_reset')) {
            @opcache_reset();
        }

        if (app()->runningInConsole()) {
            echo "Ingredients: {$filled} filled, {$kept} already had a list and were left alone.\n";
        }
    }

